import { GenericColumn, IntegerColumn, ReferenceColumn, StringColumn, SystemClassNameColumn, Table } from '../../db'

export const sys_metadata = Table({
    name: 'sys_metadata',
    schema: {
        sys_class_name: SystemClassNameColumn({
            mandatory: false,
            label: 'Class',
            read_only: false,
            active: true,
            default: 'javascript:current.getTableName();',
        }),
        sys_created_by: StringColumn({
            mandatory: false,
            label: 'Created by',
            read_only: false,
            active: true,
            maxLength: 40,
        }),
        sys_created_on: GenericColumn({
            mandatory: false,
            label: 'Created',
            read_only: false,
            active: true,
            column_type: 'glide_date_time',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        sys_mod_count: IntegerColumn({ mandatory: false, label: 'Updates', read_only: false, active: true }),
        sys_name: StringColumn({
            mandatory: false,
            label: 'Display name',
            read_only: false,
            active: true,
            maxLength: 255,
        }),
        sys_package: ReferenceColumn({
            mandatory: false,
            label: 'Package',
            read_only: true,
            active: true,
            referenceTable: 'sys_package',
        }),
        sys_policy: StringColumn({
            mandatory: false,
            label: 'Protection policy',
            read_only: false,
            active: true,
            maxLength: 40,
            choices: {
                read: { label: 'Read-only', sequence: 1, inactive: false, language: 'en' },
                protected: { label: 'Protected', sequence: 2, inactive: false, language: 'en' },
            },
        }),
        sys_scope: ReferenceColumn({
            mandatory: false,
            label: 'Application',
            read_only: false,
            active: true,
            default:
                "javascript:(((typeof parent == 'object') && parent != null && parent.getTableName() == 'sys_app') ? parent.sys_id : gs.getCurrentApplicationId())",
            referenceTable: 'sys_scope',
        }),
        sys_update_name: StringColumn({
            mandatory: false,
            label: 'Update name',
            read_only: false,
            active: true,
            maxLength: 250,
        }),
        sys_updated_by: StringColumn({
            mandatory: false,
            label: 'Updated by',
            read_only: false,
            active: true,
            maxLength: 40,
        }),
        sys_updated_on: GenericColumn({
            mandatory: false,
            label: 'Updated',
            read_only: false,
            active: true,
            column_type: 'glide_date_time',
        }),
    },
})
